import{_ as o,c as e,o as d,a4 as t}from"./chunks/framework.BYxathSa.js";const B=JSON.parse('{"title":"Q6：BFC（块级格式化上下文）是什么？触发条件和应用场景？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q6.md","filePath":"frontend/q6.md","lastUpdated":null}'),c={name:"frontend/q6.md"},l=t('<h1 id="q6-bfc-块级格式化上下文-是什么-触发条件和应用场景" tabindex="-1">Q6：BFC（块级格式化上下文）是什么？触发条件和应用场景？ <a class="header-anchor" href="#q6-bfc-块级格式化上下文-是什么-触发条件和应用场景" aria-label="Permalink to &quot;Q6：BFC（块级格式化上下文）是什么？触发条件和应用场景？&quot;">​</a></h1><p>BFC 是一个独立的渲染区域，规定了其内部的布局规则，并且<strong>内部元素的布局不会影响外部的元素</strong>。</p><p><strong>触发 BFC 的条件</strong>（任选其一即可）：</p><ul><li><code>float</code> 不为 <code>none</code></li><li><code>position</code> 为 <code>absolute</code> 或 <code>fixed</code></li><li><code>overflow</code> 不为 <code>visible</code>（如 <code>hidden</code>, <code>auto</code>, <code>scroll</code>）</li><li><code>display</code> 为 <code>inline-block</code>、<code>flex</code>、<code>grid</code>、<code>table-cell</code>、<code>flow-root</code> 等</li></ul><p><strong>BFC 的布局规则</strong>：</p><ol><li>内部的 Box 在垂直方向，一个接一个放置。</li><li>BFC 的区域不会与 float 元素重叠。</li><li>属于同一个 BFC 的相邻 Box 的垂直 margin 会发生重叠（外边距折叠）。</li><li>计算 BFC 的高度时，浮动元素也会参与计算（清除浮动）。</li></ol><p><strong>常见应用场景</strong>：</p><ul><li><strong>解决外边距折叠</strong>：将两个相邻元素置于不同 BFC，可避免 margin 重叠。</li><li><strong>清除浮动（高度塌陷）</strong>：给父元素触发 BFC（如 <code>overflow: hidden</code>），能使其包裹住浮动的子元素。</li><li><strong>两栏自适应布局</strong>：固定一侧浮动，另一侧触发 BFC（如 <code>overflow: auto</code>），它就自动不重叠，占满剩余空间。</li></ul>',8),i=[l];function n(r,a,s,_,f,p){return d(),e("div",null,i)}const u=o(c,[["render",n]]);export{B as __pageData,u as default};
